const TAU=Math.PI*2;
const C={navy:'#00273A',deep:'#001A27',sky:'#53C7DC',cyan:'#00A1C4',bone:'#E5E5E5',paper:'#EFEDE8',
  stoneLit:'#C3CDCD',stoneDark:'#0C2C3A',metalDark:'#3B525C',metalLit:'#F4F4F0'};
const DUR={places:56};
const clamp=(x,a=0,b=1)=>Math.min(b,Math.max(a,x));
const sstep=(a,b,x)=>{x=clamp((x-a)/(b-a));return x*x*(3-2*x)};
const easeIO=x=>x<.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2;
const sE=(a,b,x)=>easeIO(clamp((x-a)/(b-a)));
const win=(t,a,b,f)=>sstep(a,a+f,t)*(1-sstep(b-f,b,t));
const lerp=(a,b,k)=>a+(b-a)*k;
const HX={};const hx=h=>HX[h]||(HX[h]=[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)));
const rgba=(h,a)=>{const c=hx(h);return `rgba(${c[0]},${c[1]},${c[2]},${a})`};
const mix=(a,b,k,al=1)=>{const A=hx(a),B=hx(b);k=clamp(k);return `rgba(${A.map((v,i)=>Math.round(v+(B[i]-v)*k)).join(',')},${al})`};
const norm=v=>{const l=Math.hypot(...v);return v.map(x=>x/l)};
const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];

/* ---------- shared drawing ---------- */
function ground(ctx,W,H,P){const g=ctx.createLinearGradient(0,0,P?W*.2:W*.35,H);g.addColorStop(0,'#012C40');g.addColorStop(1,'#001722');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);}
function pools(ctx,W,H,p,P,s=1){
  const M=Math.max(W,H);
  const Q=P?[[.30,.28,.10,.05,1,0,.62,C.cyan,.22],[.70,.70,.07,.08,1,2.1,.48,C.sky,.12],[.50,.48,.10,.12,2,4,.40,C.bone,.045]]
           :[[.30,.36,.10,.06,1,0,.66,C.cyan,.22],[.72,.62,.08,.07,1,2.1,.50,C.sky,.12],[.55,.26,.12,.05,2,4,.42,C.bone,.045]];
  ctx.save();ctx.globalCompositeOperation='screen';
  for(const [ox,oy,ax,ay,k,ph,r,col,a] of Q){
    const x=(ox+ax*Math.sin(TAU*p*k+ph))*W,y=(oy+ay*Math.cos(TAU*p+ph*.7))*H,R=r*M;
    const g=ctx.createRadialGradient(x,y,0,x,y,R);
    g.addColorStop(0,rgba(col,a*s));g.addColorStop(.45,rgba(col,a*s*.4));g.addColorStop(1,rgba(col,0));
    ctx.fillStyle=g;ctx.fillRect(0,0,W,H);}
  ctx.restore();}
function vignette(ctx,W,H){const r=Math.hypot(W,H)/2;const g=ctx.createRadialGradient(W/2,H/2,r*.38,W/2,H/2,r);g.addColorStop(0,'rgba(0,10,16,0)');g.addColorStop(1,'rgba(0,10,16,.5)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);}
let GRAIN=null;
function grain(ctx,W,H){
  if(!GRAIN){const c=document.createElement('canvas');c.width=c.height=192;const x=c.getContext('2d');const d=x.createImageData(192,192);
    let s=1234567;const rnd=()=>(s=(s*16807)%2147483647)/2147483647;
    for(let i=0;i<d.data.length;i+=4){const v=rnd()*255;d.data[i]=d.data[i+1]=d.data[i+2]=v;d.data[i+3]=255;}x.putImageData(d,0,0);GRAIN=c;}
  ctx.save();ctx.globalAlpha=.06;ctx.globalCompositeOperation='overlay';ctx.fillStyle=ctx.createPattern(GRAIN,'repeat');ctx.fillRect(0,0,W,H);ctx.restore();}
function line(ctx,a,b,c,d){ctx.beginPath();ctx.moveTo(a,b);ctx.lineTo(c,d);ctx.stroke();}
function drawMono(ctx,cx,cy,h,fill,alpha=1,parts){
  const s=h/MH;ctx.save();ctx.translate(cx,cy);ctx.scale(s,s);ctx.translate(-MCX,-MCY);ctx.fillStyle=rgba(fill,alpha);
  for(const p of (parts||MP))ctx.fill(p);ctx.restore();}

/* ---------- tiny 3D: boxes, one sun ---------- */
function rotV(v,c){const cy=Math.cos(c.yaw),sy=Math.sin(c.yaw);const x=v[0]*cy-v[2]*sy,z=v[0]*sy+v[2]*cy;const cp=Math.cos(c.pitch),sp=Math.sin(c.pitch);return [x,v[1]*cp+z*sp,-v[1]*sp+z*cp];}
