/* standing seams on a roof face, eave to ridge */
function roofSeams(ctx,F,cam,px,ba){const [bl,br,tr,tl]=F.f.p,wl=Math.hypot(br[0]-bl[0],br[2]-bl[2]),n=Math.round(wl/F.b.seam);
  const at=(u,v)=>proj([0,1,2].map(i=>lerp(lerp(bl[i],br[i],u),lerp(tl[i],tr[i],u),v)),cam);ctx.beginPath();
  for(let k=1;k<n;k++){const a=at(k/n,0),c=at(k/n,1);ctx.moveTo(a[0],a[1]);ctx.lineTo(c[0],c[1]);}
  ctx.strokeStyle=rgba(C.bone,.09*ba);ctx.lineWidth=px*.8;ctx.stroke();}
/* FOR SALE on the front of the sign panel, mapped onto the face as drawn */
function signFace(ctx,pp,a){if(a<=0)return;const [BL,BR,,TL]=pp;ctx.save();
  ctx.setTransform((BR[0]-BL[0])/95,(BR[1]-BL[1])/95,(BL[0]-TL[0])/62,(BL[1]-TL[1])/62,TL[0],TL[1]);
  ctx.font='800 15px "Nunito Sans", "Segoe UI", sans-serif';if('letterSpacing' in ctx)ctx.letterSpacing='2.4px';ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillStyle=rgba(C.bone,a);ctx.fillText('FOR SALE',48.5,33);ctx.fillStyle=rgba(C.sky,a);ctx.fillRect(35,45,26,1.1);ctx.restore();}
function drawScene(ctx,shapes,cam,L,o={}){
  const A=o.alpha??1,px=o.px||1;
  if(o.grid){ctx.save();ctx.strokeStyle=rgba(C.bone,o.grid*A);ctx.lineWidth=px;ctx.beginPath();const G=o.gridN||8,s=o.gridS||1.5;
    for(let i=-G;i<=G;i++){let a=proj([i*s,0,-G*s],cam),b=proj([i*s,0,G*s],cam);ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);a=proj([-G*s,0,i*s],cam);b=proj([G*s,0,i*s],cam);ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);}
    ctx.stroke();ctx.restore();}
  if(o.pre)o.pre(ctx,cam);
  ctx.save();if(o.blur)ctx.filter=`blur(${o.blur}px)`;ctx.fillStyle=`rgba(0,8,14,${.42*A})`;ctx.beginPath();
  for(const b of shapes){if(b.h<.01||(b.a??1)<.05||b.noShadow)continue;const pts=[];
    for(const f of facesOf(b))for(const q of f.p){const k=q[1]/L[1];const r=proj([q[0]-L[0]*k,0,q[2]-L[2]*k],cam);pts.push([r[0],r[1]]);}
    const h=hull(pts);ctx.moveTo(h[0][0],h[0][1]);for(let i=1;i<h.length;i++)ctx.lineTo(h[i][0],h[i][1]);ctx.closePath();}
  ctx.fill();ctx.restore();
  const camW=camPos(cam),objs=[];
  for(const b of shapes){const ba=(b.a??1)*A;if(ba<.01||b.h<.005)continue;
    const fs=[],mn=[1e9,1e9,1e9],mx=[-1e9,-1e9,-1e9],bb=[1e9,1e9,-1e9,-1e9];
    for(const f of facesOf(b)){const n=f.p.length;for(const q of f.p)for(let k=0;k<3;k++){if(q[k]<mn[k])mn[k]=q[k];if(q[k]>mx[k])mx[k]=q[k];}
      const c=[0,1,2].map(i=>f.p.reduce((s,q)=>s+q[i],0)/n);
      const vc=rotV([c[0]-cam.tx,c[1]-cam.ty,c[2]-(cam.tz||0)],cam);const nv=rotV(f.n,cam);
      const vis=nv[0]*vc[0]+nv[1]*vc[1]+nv[2]*(vc[2]+cam.dist)<0;const m=f.roof?'roof':b.m;if(!vis&&m!=='glass')continue;
      const pp=f.p.map(q=>proj(q,cam));for(const q of pp){if(q[0]<bb[0])bb[0]=q[0];if(q[1]<bb[1])bb[1]=q[1];if(q[0]>bb[2])bb[2]=q[0];if(q[1]>bb[3])bb[3]=q[1];}
      fs.push({b,m,f,pp,vis,ba,roof:f.roof?1:0,z:pp.reduce((s,q)=>s+q[2],0)/n});}
    if(!fs.length)continue;
    fs.sort((a,b)=>(a.roof-b.roof)||(b.z-a.z));
    objs.push({fs,mn,mx,bb,part:b.part,d:Math.hypot((mn[0]+mx[0])/2-camW[0],(mn[1]+mx[1])/2-camW[1],(mn[2]+mx[2])/2-camW[2])});}
  for(const O of depthOrder(objs,camW))for(const F of O.fs){const {b,m,f,pp,ba,vis}=F;const lam=Math.max(0,dot(f.n,L));poly(ctx,pp);
    if(MAT[m]){const [d,l]=MAT[m],k=.1+.78*lam;const g=ctx.createLinearGradient(pp[3][0],pp[3][1],pp[0][0],pp[0][1]);
      g.addColorStop(0,mix(d,l,k*1.05,ba));g.addColorStop(1,mix(d,l,k*.82,ba));ctx.fillStyle=g;ctx.fill();
      ctx.strokeStyle=rgba(m==='panel'?C.sky:C.bone,(m==='panel'?.6:.09)*ba);ctx.lineWidth=px*.8;ctx.stroke();}
    else if(m==='lit'){ctx.fillStyle=rgba(C.bone,.62*ba);ctx.fill();ctx.strokeStyle=rgba(C.sky,.35*ba);ctx.lineWidth=px*.8;ctx.stroke();}
    else if(m==='glass'){ctx.fillStyle=rgba(C.sky,(vis?.07+.17*lam:.035)*ba);ctx.fill();ctx.strokeStyle=rgba(C.sky,(vis?.55:.2)*ba);ctx.lineWidth=px;ctx.stroke();
      if(vis&&o.sweep!=null){ctx.save();poly(ctx,pp);ctx.clip();const g=ctx.createLinearGradient(pp[0][0],pp[0][1],pp[2][0],pp[2][1]);const s=o.sweep;
        g.addColorStop(clamp(s-.12),rgba(C.bone,0));g.addColorStop(clamp(s),rgba(C.bone,.22*ba));g.addColorStop(clamp(s+.12),rgba(C.bone,0));ctx.fillStyle=g;ctx.fill();ctx.restore();}}
    else {ctx.fillStyle=mix(C.metalDark,C.metalLit,Math.pow(lam,1.4),ba);ctx.fill();}
    if(vis&&f.p.length===4&&Math.abs(f.n[1])<.3&&(b.fl||b.mul))faceDetail(ctx,F,cam,px,ba);
    if(vis&&f.roof&&b.seam)roofSeams(ctx,F,cam,px,ba);
    if(vis&&b.sign&&f.n[2]<-.9)signFace(ctx,pp,ba*(b.signA??1));
    if(b.scan>0&&f.n[1]>.9){ctx.strokeStyle=rgba(C.sky,.95*b.scan*ba);ctx.lineWidth=px*2.2;poly(ctx,pp);ctx.stroke();}
  }
  if(o.post)o.post(ctx,cam);}

/* ---------- 4 Places & Capabilities ---------- */
const ORDER=['ny','nj','fl'],NAMES={ny:'New York',nj:'New Jersey',fl:'Florida'},KM={ny:4.47,nj:4.75,fl:4.2};
const SAFE=.08;
const LOCK_VB=[179.75,649.7000122070312,1640.4898681640625,454.17999267578125],LP=LOCK.map(d=>new Path2D(d));
const DE_VB=[261,1125,192,192],DEP=DE.map(d=>new Path2D(d));
function drawVB(ctx,paths,vb,cx,cy,h,col,a){const s=h/vb[3];ctx.save();ctx.translate(cx,cy);ctx.scale(s,s);ctx.translate(-(vb[0]+vb[2]/2),-(vb[1]+vb[3]/2));ctx.fillStyle=rgba(col,a);for(const p of paths)ctx.fill(p);ctx.restore();}
/* Douglas Elliman affiliation: the DE badge and the name in the label face, centred on cx */
function deLine(ctx,cx,cy,h,a){if(a<=0)return;const fs=h*.36,t='DOUGLAS ELLIMAN';ctx.save();ctx.font=`800 ${fs}px "Nunito Sans", "Segoe UI", sans-serif`;
  if('letterSpacing' in ctx)ctx.letterSpacing=`${fs*.22}px`;const tw=ctx.measureText(t).width,gap=h*.42,x0=cx-(h+gap+tw)/2;
  drawVB(ctx,DEP,DE_VB,x0+h/2,cy,h,C.bone,a);ctx.fillStyle=rgba(C.bone,.88*a);ctx.textBaseline='middle';ctx.fillText(t,x0+h+gap,cy+fs*.05);ctx.restore();}
function rLayout(W,H,P){const ws=ORDER.map(k=>SP[k].w*KM[k]);const gap=300;const tot=ws.reduce((a,b)=>a+b)+2*gap;const avail=P?W*.74:W*.42,pk=avail/tot;
  let x=(W-avail)/2;const base=P?H*.58:H*.66;
  return ORDER.map((k,i)=>{const w=ws[i]*pk,h=SP[k].h*KM[k]*pk;const o={k,cx:x+w/2,cy:base-h/2,s:KM[k]*pk,base};x+=w+gap*pk;return o;});}
function stripBox(W,H,P){return P?{cx:W*.5,cy:H*.40,bw:W*.80,bh:H*.44,step:H*.80}:{cx:W*.63,cy:H*.45,bw:W*.50,bh:H*.62,step:W*.72};}
function drawState(ctx,k,cx,cy,s,em,a,px,sweepU){
  const sp=SP[k];ctx.save();ctx.translate(cx-sp.w*s/2,cy-sp.h*s/2);ctx.scale(s,s);
  const g=ctx.createLinearGradient(0,0,sp.w*.3,sp.h);g.addColorStop(0,rgba(C.cyan,(.12+.36*em)*a));g.addColorStop(1,rgba(C.cyan,(.02+.08*em)*a));
  ctx.fillStyle=g;ctx.strokeStyle=rgba(C.sky,(.55+.4*em)*a);ctx.lineWidth=(1.3+1.2*em)*px/s;ctx.lineJoin='round';
  for(const p of sp.paths){ctx.fill(p);ctx.stroke(p);}
  if(sweepU!=null&&em>.01){for(const p of sp.paths){ctx.save();ctx.clip(p);const bx=lerp(-.3,1.3,sweepU)*sp.w;const b=ctx.createLinearGradient(bx-sp.w*.15,0,bx+sp.w*.15,0);
    const ba=.22*em*a*Math.sin(Math.PI*sweepU);b.addColorStop(0,rgba(C.bone,0));b.addColorStop(.5,rgba(C.bone,ba));b.addColorStop(1,rgba(C.bone,0));ctx.fillStyle=b;ctx.fillRect(0,0,sp.w,sp.h);ctx.restore();}}
  ctx.restore();}
function grid(ctx,W,H,T,P,px){
  const a=.035+.085*win(T,20.6,36.6,2.4);const sx=W*SAFE,sw=W*(1-2*SAFE),sh=H*(1-2*SAFE);
  const cols=P?6:12,cell=sw/cols,rows=Math.floor(sh/cell),oy=H*SAFE+(sh-rows*cell)/2;
  ctx.strokeStyle=rgba(C.bone,a);ctx.lineWidth=px;ctx.beginPath();
  for(let i=0;i<=cols;i++){ctx.moveTo(sx+i*cell,oy);ctx.lineTo(sx+i*cell,oy+rows*cell);}
  for(let j=0;j<=rows;j++){ctx.moveTo(sx,oy+j*cell);ctx.lineTo(sx+sw,oy+j*cell);}ctx.stroke();}
function geo(ctx,W,H,T,P,px){
  const R=rLayout(W,H,P),S=stripBox(W,H,P);
  const camI=sE(10.5,12.1,T)+sE(15.6,17.2,T);
  const holds=[[6.2,10.9],[11.7,15.9],[16.7,21.4]];
  if(T<30){const k=sE(4.2,6.8,T),e=1-sstep(21,23.6,T);if(e<=0)return;
    R.forEach((r,i)=>{const sp=SP[r.k];const fs=Math.min(S.bw/sp.w,S.bh/sp.h)*(1-.2*sstep(21,23.6,T));
      const fx=P?S.cx:S.cx+(i-camI)*S.step,fy=P?S.cy+(i-camI)*S.step:S.cy;
      const em=k*(1-Math.min(1,Math.abs(i-camI)));
      drawState(ctx,r.k,lerp(r.cx,fx,k),lerp(r.cy,fy,k),lerp(r.s,fs,k),em,e,px,clamp((T-holds[i][0])/(holds[i][1]-holds[i][0])));});
    names(ctx,W,H,R,1-sstep(4,5.2,T),P);}
  else{const a=sstep(53,55.6,T);if(a<=0)return;R.forEach(r=>drawState(ctx,r.k,r.cx,r.cy,r.s,0,a,px));names(ctx,W,H,R,sstep(53.6,55.8,T),P);}}
function names(ctx,W,H,R,a,P){if(a<=0)return;const fs=P?W*.027:H*.028;ctx.save();ctx.font=`800 ${fs}px "Nunito Sans", "Segoe UI", sans-serif`;
  if('letterSpacing' in ctx)ctx.letterSpacing=`${fs*.18}px`;ctx.textAlign='center';ctx.fillStyle=rgba(C.bone,.92*a);
  R.forEach(r=>ctx.fillText(NAMES[r.k].toUpperCase(),r.cx,r.base+fs*2.1));ctx.restore();}
function restLock(W,H,P){const w=P?W*.78:W*.50;return {cx:W*.5,cy:P?H*.25:H*.27,h:w*LOCK_VB[3]/LOCK_VB[2]};}
function brandRest(ctx,W,H,T,P,px){
  const a=T<30?1-sstep(3.8,5.4,T):sstep(53.2,55.6,T);if(a<=0)return;
  const d=T<30?sstep(3.8,5.4,T):0,L=restLock(W,H,P);
  drawVB(ctx,LP,LOCK_VB,L.cx,L.cy-d*H*.02,L.h,C.bone,a);
  deLine(ctx,W*.5,H*.86,P?W*.052:H*.06,a*.9);}

/* ---- Resale: a home on its lawn, then a for-sale sign ---- */
const LAWN={l:[-6.9,7.0,-4.8,3.9],p:[-4.7,3.9,-4.8,3.9]};
const backOut=u=>{const c1=1.70158,c3=c1+1;return 1+c3*Math.pow(u-1,3)+c1*Math.pow(u-1,2);};
